pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        vm.prank(address(this));
        c.XBornID();

        address user1 = address(0x1);
        address user2 = address(0x2);
        address user3 = address(0x3);

        vm.prank(user1);
        c.getTokens();

        vm.prank(user2);
        c.getTokens();

        vm.prank(user3);
        c.getTokens();

        uint256 remaining = c.totalRemaining();
        assertTrue(remaining > 0, "totalRemaining should be positive in reference");
    }
}
